import * as PIXI from 'pixi.js';
import { DEFAULT_REEL_ANIMATION_CONFIG, ReelAnimationConfig, ReelSpinMethod } from '../config/ReelConfig';
import { EventBus, GameEvents } from '../core/EventBus';
import { ReelView } from '../views/ReelView';
import { ReelContainer } from '../views/ReelContainer';

export class ReelAnimationManager {
    private reelContainer: ReelContainer;
    private eventBus = EventBus.getInstance();
    private targetMatrix: number[][] | null = null;
    private isSpinning = false;
    private cancelRequested = false;

    constructor(ReelContainer: ReelContainer) {
        this.reelContainer = ReelContainer;
        this.eventBus.on(GameEvents.SPIN_RESPONSE_RECEIVED, (matrix: number[][]) => {
            if (this.isSpinning) {
                this.targetMatrix = matrix;
            }
        });
    }

    public async spinReels(): Promise<void> {
        this.isSpinning = true;
        this.cancelRequested = false;
        this.targetMatrix = null;

        try {
            const hasCascadingReel = this.reelContainer.reels.some((_, index) => {
                const reelConfig = this.getReelAnimationConfig(index);
                return reelConfig.isCascading;
            });

            if (!hasCascadingReel) {
                await Promise.all(this.reelContainer.reels.map((reel, index) => {
                    const reelConfig = this.getReelAnimationConfig(index);
                    const startDelayMs = reelConfig.method === 'staggered' ? index * 100 : 0;

                    return new Promise<void>((resolve) => {
                        const start = () => {
                            void this.spinSingleReel(reel, index).then(() => resolve());
                        };

                        if (startDelayMs > 0) {
                            setTimeout(start, startDelayMs);
                            return;
                        }

                        start();
                    });
                }));
                return;
            }

            for (let index = 0; index < this.reelContainer.reels.length; index++) {
                await this.spinSingleReel(this.reelContainer.reels[index], index);
            }
        } finally {
            this.isSpinning = false;
            this.targetMatrix = null;
        }
    }

    public cancelSpin(): void {
        this.cancelRequested = true;
    }

    private getReelAnimationConfig(reelIndex: number): ReelAnimationConfig {
        return {
            ...DEFAULT_REEL_ANIMATION_CONFIG,
        };
    }

    private runNormalReelSpin(
        reel: ReelView,
        reelConfig: ReelAnimationConfig,
        spinState: { elapsed: number; speed: number },
        ticker: PIXI.Ticker,
    ): number {
        if (spinState.elapsed <= 0.3) {
            const t = spinState.elapsed / 0.3;
            spinState.speed = reelConfig.spinSpeed * t;
        } else {
            spinState.speed = reelConfig.spinSpeed;
        }

        return (spinState.speed * ticker.deltaMS) / 16.67;
    }

    private runImmediateReelStop(
        reel: ReelView,
        reelIndex: number,
        reelConfig: ReelAnimationConfig,
        finalColumnValues: number[],
        resolve: () => void,
    ): void {
        void reel.startStopBounce(reelConfig.bounceDuration, reelConfig.bounceDepth).then(() => {
            this.eventBus.emit(GameEvents.REEL_STOPPED, {
                reelIndex,
                reel,
                values: finalColumnValues,
                method: reelConfig.method,
            });
            resolve();
        });
    }

    private startImmediateReelSpin(
        reel: ReelView,
        reelIndex: number,
        reelConfig: ReelAnimationConfig,
    ): Promise<void> {
        return new Promise(async (resolve) => {
            if (this.cancelRequested) {
                resolve();
                
                return;
            }

            const spinStartedAt = performance.now();
            const spinState = { elapsed: 0, speed: 0 };
            const minimumSpinSeconds = Math.max(0, reelConfig.minSpinDuration ?? 2);
            const minimumSpinMs = minimumSpinSeconds * 1000;
            let finalColumnValues: number[] | null = null;
            let stopQueueStarted = false;
            let responseReceivedAt: number | null = null;
            let decelerationStarted = false;
            let decelerationElapsed = 0;
            let decelerationDuration = 0;
            let remainingStopDistance = 0;

            const tick = (ticker: PIXI.Ticker) => {
                if (this.cancelRequested) {
                    reel.clearStopSymbols();
                    reel.blurFilter.strengthY = 0;
                    PIXI.Ticker.shared.remove(tick);
                    resolve();
                    return;
                }

                spinState.elapsed += ticker.deltaMS / 1000;
                const scrollStep = this.runNormalReelSpin(reel, reelConfig, spinState, ticker);

                if (!stopQueueStarted && this.targetMatrix) {
                    finalColumnValues = this.targetMatrix[reelIndex] ?? [];
                    reel.prepareStopSymbols(finalColumnValues);
                    stopQueueStarted = true;
                    responseReceivedAt = performance.now();
                }

                let nextScrollStep = scrollStep;
                if (decelerationStarted) {
                    const previousProgress = decelerationElapsed / decelerationDuration;
                    decelerationElapsed += ticker.deltaMS / 1000;
                    const progress = Math.min(decelerationElapsed / decelerationDuration, 1);
                    const averageSpeed = reelConfig.spinSpeed *
                        (1 - (Math.min(previousProgress, 1) + progress) / 2);
                    spinState.speed = reelConfig.spinSpeed * (1 - progress);
                    nextScrollStep = progress >= 1
                        ? remainingStopDistance
                        : Math.min((averageSpeed * ticker.deltaMS) / 16.67, remainingStopDistance);
                }

                const stopSequenceReady = reel.scrollSymbols(nextScrollStep);
                if (decelerationStarted) {
                    remainingStopDistance -= nextScrollStep;
                    if (decelerationElapsed >= decelerationDuration || remainingStopDistance <= 0.001) {
                        reel.clearStopSymbols();
                        reel.blurFilter.strengthY = 0;
                        PIXI.Ticker.shared.remove(tick);
                        this.runImmediateReelStop(
                            reel,
                            reelIndex,
                            reelConfig,
                            finalColumnValues ?? [],
                            () => resolve(),
                        );
                        return;
                    }
                } else if (responseReceivedAt !== null) {
                    const earliestStopAt = Math.max(
                        responseReceivedAt,
                        spinStartedAt + minimumSpinMs,
                    );

                    if (performance.now() >= earliestStopAt) {
                        remainingStopDistance = reel.getDistanceToNextRowBoundary();
                        decelerationDuration = remainingStopDistance / (reelConfig.spinSpeed * 30);
                        decelerationStarted = true;
                    }
                }

                reel.blurFilter.strengthY = spinState.speed * 0.2;
            };

            PIXI.Ticker.shared.add(tick);
        });
    }

    private async startCascadeReelSpin(
        reel: ReelView,
        reelIndex: number,
        reelConfig: ReelAnimationConfig,
    ): Promise<void> {
        const minimumSpinMs = Math.max(0, (reelConfig.minSpinDuration ?? 2) * 1000);
        const startTime = performance.now();

        while (!this.cancelRequested && !this.targetMatrix) {
            await new Promise((resolve) => setTimeout(resolve, 16));
        }

        if (this.cancelRequested || !this.targetMatrix) {
            return;
        }

        const elapsedMs = performance.now() - startTime;
        const remainingMinWaitMs = Math.max(0, minimumSpinMs - elapsedMs);
        if (remainingMinWaitMs > 0) {
            await new Promise((resolve) => setTimeout(resolve, remainingMinWaitMs));
        }

        // Matrix is [reel][row], and row 0 is the top visible slot.
        // Never reverse this array for cascade updates.
        const finalColumnValues = [...(this.targetMatrix[reelIndex] ?? [])];
        const rowDelayMs = Math.max(50, Math.round((reelConfig.cascadeDelay || 0.1) * 1000 / Math.max(reel.rows, 1)));

        await reel.cascadeUpdateColumn(finalColumnValues, rowDelayMs);

        this.eventBus.emit(GameEvents.REEL_STOPPED, {
            reelIndex,
            reel,
            values: finalColumnValues,
            method: reelConfig.method,
        });
    }

    private spinSingleReel(reel: ReelView, reelIndex: number): Promise<void> {
        const reelConfig = this.getReelAnimationConfig(reelIndex);

        if (reelConfig.isCascading) {
            return this.startCascadeReelSpin(reel, reelIndex, reelConfig);
        }

        return this.startImmediateReelSpin(reel, reelIndex, reelConfig);
    }
}