export type ReelSpinMethod = 'staggered' | 'reverse' | 'simultaneous';

export interface ReelAnimationConfig {
    method: ReelSpinMethod;
    cascadeDelay: number;
    isCascading: boolean;
    spinSpeed: number;
    minSpinDuration: number;
    bounceDuration: number;
    bounceDepth: number;
}

export const DEFAULT_REEL_ANIMATION_CONFIG: ReelAnimationConfig = {
    method: 'staggered',
    cascadeDelay: 2,
    isCascading: false,
    spinSpeed: 25,
    minSpinDuration: 2,
    bounceDuration: 0.28,
    bounceDepth: 8,
};


