import { WIN_CELEBRATION_TYPE } from '../config/WinCelebrationConfig';
import { GsapWinParticleEffect } from './WinParticleEffect';
import { PixiParticleWinEffect } from './PixiParticleWinEffect';

export function createWinCelebrationEffect(): GsapWinParticleEffect | PixiParticleWinEffect {
    switch (WIN_CELEBRATION_TYPE) {
        case 'gsap':
            return new GsapWinParticleEffect();
        case 'pixiParticle':
            return new PixiParticleWinEffect();
    }
}