import { EventBus, GameEvents } from "../core/EventBus";
import { WinEvaluator } from "./WinEvaluator";

interface SpinRequest {
    betAmount: number;
    lines: number;
}

interface SpinResponse {
    matrix: number[][]; // e.g. 3x5 reel matrix
    totalWin: number;
    freeSpinsTriggered: boolean;
}
export class NetworkService {
    private eventBus = EventBus.getInstance();

    public async getDummayData(request: SpinRequest): Promise<SpinResponse> {
        return new Promise((resolve, reject) => {
            const dummyResponse: SpinResponse = {
                matrix: [
                    [0, 1, 2],
                    [3, 4, 5],
                    [6, 7, 0],
                    [1, 2, 3],
                    [4, 5, 6],
                ],
                totalWin: 100,
                freeSpinsTriggered: false
            };
            resolve(dummyResponse);

        });
    }

    // Mock API Call to Casino Backend
    public async requestSpinData(request: SpinRequest): Promise<SpinResponse> {
        return new Promise((resolve, reject) => {
            // Basic validation
            if (request.betAmount <= 0) {
                reject(new Error("Invalid bet amount"));
                return;
            }

            // Network delay simulation (500ms)
            setTimeout(() => {
                const rows = 3;
                const cols = 5;
                const symbolPool = [0, 1, 2, 3, 4, 5, 6, 7];
                const randomMatrix = Array.from({ length: cols }, () =>
                    Array.from({ length: rows }, () =>
                        symbolPool[Math.floor(Math.random() * symbolPool.length)]
                    )
                );
                const mockResponse: SpinResponse = {
                    matrix: randomMatrix,
                    totalWin: WinEvaluator.evaluate(randomMatrix).totalWin,
                    freeSpinsTriggered: true
                };
                this.eventBus.emit(GameEvents.SPIN_RESPONSE_RECEIVED, mockResponse.matrix);
                resolve(mockResponse);
            }, 500); 
        });
    }
}